-- Generated by scripts/build_compiled.py from src/fraudrules/rules/payee-fraud/pf-002-outsized-first-payment.yaml. Do not edit.
-- PF-002 First payment to a new payee far larger than any recent known payment
SELECT 'PF-002' AS rule_id, 'transactions' AS anchor_table, a.id AS anchor_id
FROM transactions AS a
JOIN transactions AS b ON b.account_id = a.account_id AND b.ts <= a.ts AND b.ts > a.ts - 7776000
WHERE (a.direction = 'out' AND a.channel IN ('wire', 'ach', 'rtp') AND a.counterparty_new = 1) AND (b.direction = 'out' AND b.channel IN ('wire', 'ach', 'rtp', 'p2p', 'check') AND b.counterparty_new = 0)
GROUP BY a.id
HAVING (COUNT(*) >= 3 AND MAX(a.amount_cents) * 100 >= MAX(b.amount_cents) * 300);
